def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    counts = Counter(v for row in grid for v in row)
    marker = min((v for v in counts if v != 0),
                 key=lambda v: counts[v])
    pts = {(r, c) for r in range(h) for c in range(w)
           if grid[r][c] == marker}

    # For a larger noisy marker, use its largest 4-connected component.
    if len(pts) > 5:
        comps = []
        unseen = set(pts)
        while unseen:
            start = unseen.pop()
            comp = {start}
            q = [start]
            while q:
                r, c = q.pop()
                for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if p in unseen:
                        unseen.remove(p)
                        comp.add(p)
                        q.append(p)
            comps.append(comp)
        pts = max(comps, key=len)

    r0 = min(r for r, c in pts)
    c0 = min(c for r, c in pts)
    shape = {(r-r0, c-c0) for r, c in pts}

    variants = set()
    for flip in (1, -1):
        for k in range(4):
            transformed = []
            for r, c in shape:
                c *= flip
                for _ in range(k):
                    r, c = c, -r
                transformed.append((r, c))
            mr = min(r for r, c in transformed)
            mc = min(c for r, c in transformed)
            variants.add(frozenset((r-mr, c-mc) for r, c in transformed))

    out = [row[:] for row in grid]
    for sh in variants:
        sh_h = max(r for r, c in sh) + 1
        sh_w = max(c for r, c in sh) + 1
        for r in range(h-sh_h+1):
            for c in range(w-sh_w+1):
                cells = [(r+dr, c+dc) for dr, dc in sh]
                if all(grid[a][b] == 0 for a, b in cells):
                    for a, b in cells:
                        out[a][b] = marker
    return out
